module word_search(\n    input clk,\n    input rst_n,\n    input start,\n    input [63:0] query_word,\n    output reg [15:0] result,\n    output reg done\n);\n\n    // Database storage\n    reg [63:0] database [0:7];\n\n    // State definitions\n    localparam [1:0] IDLE    = 2'd0;\n    localparam [1:0] COMPARE = 2'd1;\n    localparam [1:0] NEXT    = 2'd2;\n    localparam [1:0] DONE_ST = 2'd3;\n\n    reg [1:0] state, next_state;\n    reg [2:0] index;\n    reg [15:0] lcp_sum;\n    reg [15:0] exact_matches;\n    wire [63:0] current_word;\n\n    // Current word selection\n    assign current_word = database[index];\n\n    // LCP computation (unrolled)\n    reg [3:0] lcp_temp;\n    always @(*) begin\n        lcp_temp = 4'd0;\n        if (query_word[7:0] == current_word[7:0]) begin\n            lcp_temp = 4'd1;\n            if (query_word[15:8] == current_word[15:8]) begin\n                lcp_temp = 4'd2;\n                if (query_word[23:16] == current_word[23:16]) begin\n                    lcp_temp = 4'd3;\n                    if (query_word[31:24] == current_word[31:24]) begin\n                        lcp_temp = 4'd4;\n                        if (query_word[39:32] == current_word[39:32]) begin\n                            lcp_temp = 4'd5;\n                            if (query_word[47:40] == current_word[47:40]) begin\n                                lcp_temp = 4'd6;\n                                if (query_word[55:48] == current_word[55:48]) begin\n                                    lcp_temp = 4'd7;\n                                    if (query_word[63:56] == current_word[63:56]) begin\n                                        lcp_temp = 4'd8;\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\n\n    // State register\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            index <= 3'd0;\n            lcp_sum <= 16'd0;\n            exact_matches <= 16'd0;\n            result <= 16'd0;\n            done <= 1'b0;\n        end else begin\n            state <= next_state;\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        index <= 3'd0;\n                        lcp_sum <= 16'd0;\n                        exact_matches <= 16'd0;\n                    end\n                end\n\n                COMPARE: begin\n                    lcp_sum <= lcp_sum + lcp_temp;\n                    if (lcp_temp == 4'd8) begin\n                        exact_matches <= exact_matches + 16'd1;\n                    end\n                end\n\n                NEXT: begin\n                    if (index < 3'd7) begin\n                        index <= index + 3'd1;\n                    end\n                end\n\n                DONE_ST: begin\n                    result <= lcp_sum + exact_matches;\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: next_state = (start) ? COMPARE : IDLE;\n            \n            COMPARE: next_state = NEXT;\n            \n            NEXT: begin\n                if (index < 3'd7) begin\n                    next_state = COMPARE;\n                end else begin\n                    next_state = DONE_ST;\n                end\n            end\n            \n            DONE_ST: next_state = DONE_ST;\n            \n            default: next_state = IDLE;\n        endcase\n    end\n\nendmodule